function jwtPayload(token) {
    const part = token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
    const text = (typeof atob === 'function') ? atob(part) : Buffer.from(part, 'base64').toString();
    return JSON.parse(text);
}

